/* ── چوونەژوورەوە بە پەنجەمۆر یان ڕوو ── */
const bioAvailable = async () => {
  try {
    if (!window.PublicKeyCredential) return false;
    return await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
  } catch { return false; }
};
const bioSave = async (id, pw) => {
  try {
    const ch = crypto.getRandomValues(new Uint8Array(32));
    const uid8 = new TextEncoder().encode(id).slice(0, 64);
    const cred = await navigator.credentials.create({
      publicKey: {
        challenge: ch, rp: { name: "Sarraf" },
        user: { id: uid8, name: id, displayName: id },
        pubKeyCredParams: [{ type: "public-key", alg: -7 }, { type: "public-key", alg: -257 }],
        authenticatorSelection: { authenticatorAttachment: "platform", userVerification: "required" },
        timeout: 60000,
      },
    });
    if (!cred) return false;
    localStorage.setItem("bio", JSON.stringify({ id, pw, cid: btoa(String.fromCharCode(...new Uint8Array(cred.rawId))) }));
    return true;
  } catch { return false; }
};
const bioLogin = async () => {
  try {
    const saved = JSON.parse(localStorage.getItem("bio") || "null");
    if (!saved?.cid) return null;
    const raw = Uint8Array.from(atob(saved.cid), (c) => c.charCodeAt(0));
    const ok = await navigator.credentials.get({
      publicKey: {
        challenge: crypto.getRandomValues(new Uint8Array(32)),
        allowCredentials: [{ type: "public-key", id: raw }],
        userVerification: "required", timeout: 60000,
      },
    });
    return ok ? saved : null;
  } catch { return null; }
};

function Login() {
  const [id, setId] = useState("");
  const [pw, setPw] = useState("");
  const [show, setShow] = useState(false);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  // ئیمەیل بێت وەک خۆی، ژمارە بێت دەکرێت بە ئیمەیلی ناوخۆیی
  const toEmail = (v) => {
    const t = String(v).trim();
    if (t.includes("@")) return t.toLowerCase();
    return `${t.replace(/\D/g, "")}@sarraf.local`;
  };

  const [bio, setBio] = useState(false);
  useEffect(() => {
    (async () => {
      const has = localStorage.getItem("bio");
      if (has && await bioAvailable()) setBio(true);
    })();
  }, []);

  const go = async (ov) => {
    const uid2 = ov?.id ?? id, pw2 = ov?.pw ?? pw;
    if (!uid2 || !pw2) return setErr(tr("ژمارە/ئیمەیل و وشەی نهێنی پێویستە"));
    setBusy(true); setErr("");
    const { error } = await supabase.auth.signInWithPassword({ email: toEmail(uid2), password: pw2 });
    if (error) setErr(tr("زانیارییەکان هەڵەن — دووبارە هەوڵ بدە"));
    else if (!ov && await bioAvailable() && !localStorage.getItem("bio")) {
      // پێشنیاری دامەزراندنی پەنجەمۆر
      setTimeout(() => { if (confirm(tr("دەتەوێت جاری داهاتوو بە پەنجەمۆر بچیتە ژوورەوە؟"))) bioSave(uid2, pw2); }, 900);
    }
    setBusy(false);
  };

  const goBio = async () => {
    setBusy(true); setErr("");
    const saved = await bioLogin();
    if (!saved) { setErr(tr("نەتوانرا پشتڕاست بکرێتەوە")); setBusy(false); return; }
    await go(saved);
  };

  return (
    <div dir={LANGS[_lang]?.dir || "rtl"} data-role="admin"
      className="min-h-screen flex items-center justify-center p-6 relative overflow-hidden"
      style={{ background: "var(--bg)" }}>

      <div className="absolute inset-x-0 -top-24 h-[420px] pointer-events-none"
        style={{ background: "radial-gradient(60% 100% at 50% 0%, rgba(224,169,74,.14), transparent 72%)" }} />
      <div className="absolute -bottom-32 -start-24 w-[400px] h-[400px] rounded-full pointer-events-none"
        style={{ background: "radial-gradient(circle, rgba(124,107,245,.09), transparent 70%)" }} />

      <div className="w-full max-w-[380px] relative rise">
        <div className="text-center mb-10">
          <div className="w-16 h-16 rounded-[22px] mx-auto mb-5 flex items-center justify-center"
            style={{ background: "linear-gradient(155deg, #E0A94A, #A9772C)",
                     boxShadow: "0 12px 36px -10px rgba(224,169,74,.6), inset 0 1px 0 rgba(255,255,255,.3)" }}>
            <Vault className="w-7 h-7 text-white" />
          </div>
          <h1 className="text-[24px] font-semibold tracking-tight" style={{ color: "var(--txt)" }}>
            {tr("سیستەمی دراو")}
          </h1>
          <p className="text-[13px] mt-1.5" style={{ color: "var(--txt-3)" }}>
            {tr("کڕین و فرۆشتن · قاسە · حیسابات")}
          </p>
        </div>

        <div className="space-y-3">
          <div>
            <Lbl>{tr("ژمارەی مۆبایل یان ئیمەیل")}</Lbl>
            <input dir="ltr" type="text" autoComplete="username" value={id} onChange={(e) => setId(e.target.value)}
              placeholder="07701234567" onKeyDown={(e) => e.key === "Enter" && go()}
              className="w-full px-4 py-3.5 text-[15px] outline-none"
              style={{ ...fieldSty, fontFamily: "'IBM Plex Mono', monospace" }}
              onFocus={onFoc} onBlur={onBlr} />
          </div>
          <div>
            <Lbl>{tr("وشەی نهێنی")}</Lbl>
            <div className="relative">
              <input type={show ? "text" : "password"} autoComplete="current-password" value={pw}
                onChange={(e) => setPw(e.target.value)} onKeyDown={(e) => e.key === "Enter" && go()}
                className="w-full ps-4 pe-12 py-3.5 text-[15px] outline-none"
                style={fieldSty} onFocus={onFoc} onBlur={onBlr} />
              <button type="button" onClick={() => setShow(!show)} tabIndex={-1}
                className="absolute end-3 top-1/2 -translate-y-1/2 p-1.5 tap"
                style={{ color: "var(--txt-3)" }}>
                {show ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </button>
            </div>
          </div>

          {err && (
            <div className="text-[13px] rounded-[var(--r-sm)] px-4 py-3 flex items-center gap-2.5 drop"
              style={{ background: "var(--neg-bg)", color: "var(--neg)", border: "1px solid color-mix(in srgb, var(--neg) 26%, transparent)" }}>
              <AlertTriangle className="w-4 h-4 shrink-0" /> {err}
            </div>
          )}

          <Btn onClick={() => go()} disabled={busy} className="w-full !py-3.5 !text-[15px] mt-1">
            {busy ? "..." : tr("چوونە ژوورەوە")}
          </Btn>

          {bio && (
            <button onClick={goBio} disabled={busy}
              className="w-full flex items-center justify-center gap-2.5 py-3.5 rounded-[var(--r-sm)] tap text-[14px] font-semibold"
              style={{ background: "var(--glass)", border: "1px solid var(--line)", color: "var(--txt-2)" }}>
              <Fingerprint className="w-[18px] h-[18px]" /> {tr("پەنجەمۆر یان ڕوو")}
            </button>
          )}
        </div>

        <div className="flex justify-center gap-1.5 mt-8">
          {Object.entries(LANGS).map(([k, v]) => (
            <button key={k} onClick={() => { setLangGlobal(k); location.reload(); }}
              className="px-3.5 py-1.5 rounded-full text-[11.5px] font-semibold tap"
              style={_lang === k
                ? { background: "rgba(224,169,74,.16)", color: "#E0A94A" }
                : { color: "var(--txt-3)" }}>
              {v.name}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

